'use client';

import { useEffect, useMemo, useRef, useState } from 'react';

import {
  useAutoplay,
  type AutoplayStep,
} from '@/registry/ndeko/hooks/use-autoplay';
import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge, type BadgeProps } from '@/registry/ndeko/ui/badge';
import { Segments, type Segment } from '@/registry/ndeko/ui/segments';

import { ringOf, TOP_EM } from './_parts/seal-ring';
import { useHover } from './_parts/use-hover';
import { usePlayWhileSeen } from './_parts/use-play-while-seen';

type RingStyle = React.CSSProperties & { '--r': string };

/** The ring is one turn long at normal speed over this many seconds, and the speed it turns at is a playback rate of it. */
const TURN_SECONDS = 60;

const DEFAULT_SECONDS_PER_TURN = 28;

const TURN_KEYFRAMES: Keyframe[] = [
  { transform: 'rotate(0deg)' },
  { transform: 'rotate(360deg)' },
];

/**
 * The letters stand in a ring that has the size of the seal's text. When a long phrase makes them
 * smaller, the ring is given the smaller text size and the top of the letters is measured in it.
 */
function ringStyleOf(scale: number): RingStyle {
  const size = Math.round(scale * 1000) / 1000;
  const top = Math.round((TOP_EM / size) * 1000) / 1000;
  return { fontSize: `${size}em`, '--r': `${top}em` };
}

function rateOf(secondsPerTurn: number) {
  const isUsable = Number.isFinite(secondsPerTurn) && secondsPerTurn > 0;
  if (!isUsable) {
    return TURN_SECONDS / DEFAULT_SECONDS_PER_TURN;
  }
  return TURN_SECONDS / secondsPerTurn;
}

export type SealProps = {
  /** The line that turns round the ring. It repeats until the ring is full, so a phrase of two to four words fits best. */
  text: string;
  /** The word at the centre, which stays still. Keep it short. */
  label: string;
  /** The colour of the whole seal, one of the colours of a badge. */
  variant?: BadgeProps['variant'];
  /** How long one full turn takes, in seconds. */
  secondsPerTurn?: number;
  /** Stops the ring. It also holds off screen, in a hidden tab, under the pointer and under reduced motion. */
  isTurning?: boolean;
  className?: string;
};

/**
 * A round seal in one colour: a line of text turns slowly round a label that stays still. The ring
 * is one element turned by a transform that the browser runs off the main thread, and it holds
 * wherever nobody can read it, so the seal costs nothing off screen. The seal is read as one image.
 */
export function Seal({
  text,
  label,
  variant = 'default',
  secondsPerTurn = DEFAULT_SECONDS_PER_TURN,
  isTurning = true,
  className,
}: SealProps) {
  const { ref, isPlaying } = usePlayWhileSeen<HTMLSpanElement>();
  const { isHovered, hoverHandlers } = useHover();
  const ringRef = useRef<HTMLSpanElement>(null);
  const turn = useRef<Animation | null>(null);
  const ring = useMemo(() => ringOf(text), [text]);
  const shouldTurn = isPlaying && isTurning && !isHovered;
  const rate = rateOf(secondsPerTurn);

  useEffect(() => {
    const element = ringRef.current;
    if (!element) {
      return;
    }
    const animation = element.animate(TURN_KEYFRAMES, {
      duration: TURN_SECONDS * 1000,
      iterations: Number.POSITIVE_INFINITY,
    });
    animation.pause();
    turn.current = animation;
    return () => {
      animation.cancel();
      turn.current = null;
    };
  }, []);

  useEffect(() => {
    turn.current?.updatePlaybackRate(rate);
  }, [rate]);

  useEffect(() => {
    const animation = turn.current;
    if (!animation) {
      return;
    }
    if (shouldTurn) {
      animation.play();
      return;
    }
    animation.pause();
  }, [shouldTurn]);

  return (
    <span ref={ref} className='inline-flex shrink-0' {...hoverHandlers}>
      <Badge
        variant={variant}
        role='img'
        aria-label={`${label}, ${text}`}
        className={cn(
          'hairline-ring relative size-[11em] overflow-hidden rounded-full p-0 ring-current/25',
          className
        )}
      >
        <span
          ref={ringRef}
          aria-hidden='true'
          style={ringStyleOf(ring.scale)}
          className='absolute inset-0 select-none *:absolute *:top-[calc(50%-var(--r))] *:left-[calc(50%-0.5em)] *:h-(--r) *:w-[1em] *:origin-bottom *:text-center *:leading-none'
        >
          {ring.letters.map((letter, index) => (
            <span key={index} style={{ rotate: `${letter.angle}deg` }}>
              {letter.char}
            </span>
          ))}
        </span>
        <span
          aria-hidden='true'
          className='absolute inset-[2em] rounded-full bg-current/7'
        />
        <span className='relative w-[5.6em] text-center text-[1.15em] leading-tight font-semibold text-balance'>
          {label}
        </span>
      </Badge>
    </span>
  );
}

type Pace = 'calm' | 'quick' | 'paused';

const PACES: Segment<Pace>[] = [
  { value: 'calm', label: 'Calm' },
  { value: 'quick', label: 'Quick' },
  { value: 'paused', label: 'Paused' },
];

const SECONDS_PER_TURN: Record<Pace, number> = {
  calm: 28,
  quick: 9,
  paused: 28,
};

/** Long enough at each pace for the difference to be seen before the demonstration goes round again. */
const CALM_SHOWN_MS = 6000;

const QUICK_SHOWN_MS = 5000;

export default function Badge16() {
  const [pace, setPace] = useState<Pace>('calm');
  const { isHovered, hoverHandlers } = useHover();
  const steps: AutoplayStep[] = [
    { after: CALM_SHOWN_MS, run: () => setPace('quick') },
    { after: QUICK_SHOWN_MS, run: () => setPace('calm') },
  ];
  const { ref } = useAutoplay(steps, {
    loopAfter: 0,
    onReset: () => setPace('calm'),
    isEnabled: !isHovered,
  });
  const isTurning = pace !== 'paused';

  useKeptHeight(ref);

  return (
    <div
      ref={ref}
      className='flex w-full max-w-[22rem] flex-col items-center gap-5'
      {...hoverHandlers}
    >
      <Seal
        text='Roasted in Goma'
        label='Small batch'
        secondsPerTurn={SECONDS_PER_TURN[pace]}
        isTurning={isTurning}
      />
      <Segments
        value={pace}
        segments={PACES}
        onValueChange={setPace}
        label='Turning pace'
      />
    </div>
  );
}

/** The radius of the line the letters are centred on, in em of the seal. */
const MIDDLE_EM = 4.4;

/** How far from the centre of the seal the top of a letter stands, in em of the seal. */
export const TOP_EM = 4.9;

const CIRCUMFERENCE_EM = 2 * Math.PI * MIDDLE_EM;

const SEPARATOR = ' · ';

/** One more repeat of the phrase is fitted only when its letters can stay at this share of their size or more. */
const LEAST_SHRINK = 0.85;

const DEFAULT_ADVANCE_EM = 0.56;

/**
 * How wide a letter is, in em, for a typical sans face. The seal spreads its letters by these
 * widths so that an i and an m do not stand the same distance apart; the real face may differ a
 * little, and the ring still closes since the widths are only shares of the circumference.
 */
const ADVANCE_GROUPS: readonly (readonly [chars: string, advance: number])[] = [
  [' ', 0.28],
  ['ijl', 0.23],
  ["'", 0.2],
  [',.:;!|', 0.27],
  ['·', 0.3],
  ['ft', 0.29],
  ['I-', 0.3],
  ['r', 0.34],
  ['ckvxysJz', 0.5],
  ['L', 0.56],
  ['FTZ', 0.61],
  ['ABEKPSVXY', 0.67],
  ['CDHNRU', 0.72],
  ['w', 0.72],
  ['GOQ', 0.78],
  ['mM', 0.83],
  ['W', 0.94],
];

export type RingLetter = {
  char: string;
  /** Degrees clockwise from the top, where the letter stands. */
  angle: number;
};

export type Ring = {
  letters: RingLetter[];
  /** The size of the letters as a share of the text size of the seal: 1, or less when the phrase is longer than the ring. */
  scale: number;
};

type Slot = {
  char: string;
  /** Where the middle of the letter's slot lies along the ring, in em. */
  centre: number;
};

function advancesOf(groups: typeof ADVANCE_GROUPS) {
  const advances = new Map<string, number>();
  for (const [chars, advance] of groups) {
    for (const char of chars) {
      advances.set(char, advance);
    }
  }
  return advances;
}

const ADVANCES = advancesOf(ADVANCE_GROUPS);

function advanceOf(char: string) {
  return ADVANCES.get(char) ?? DEFAULT_ADVANCE_EM;
}

function widthOf(chars: readonly string[]) {
  let total = 0;
  for (const char of chars) {
    total += advanceOf(char);
  }
  return total;
}

/** How many times the phrase goes round: as many as fit, or one more when the letters need not shrink much to make room. */
function repeatsFor(unitWidth: number) {
  const fits = CIRCUMFERENCE_EM / unitWidth;
  const lower = Math.max(1, Math.floor(fits));
  const upper = lower + 1;
  const upperScale = CIRCUMFERENCE_EM / (upper * unitWidth);
  if (upperScale >= LEAST_SHRINK) {
    return upper;
  }
  return lower;
}

/** Every letter gets a slot as wide as itself plus its share of what the ring has left over, so the slots fill the ring exactly. */
function slotsOf(
  unit: readonly string[],
  repeats: number,
  scale: number,
  spacing: number
) {
  const slots: Slot[] = [];
  let cursor = 0;
  for (let repeat = 0; repeat < repeats; repeat += 1) {
    for (const char of unit) {
      const width = advanceOf(char) * scale + spacing;
      slots.push({ char, centre: cursor + width / 2 });
      cursor += width;
    }
  }
  return slots;
}

function angleOf(position: number, offset: number) {
  const degrees = (position / CIRCUMFERENCE_EM) * 360 - offset;
  return Math.round(degrees * 100) / 100;
}

/**
 * The letters of a phrase laid round a ring, the phrase repeated, a dot between two repeats, the
 * first phrase centred at the top. The same text always gives the same ring.
 */
export function ringOf(text: string): Ring {
  const phrase = Array.from(text.trim());
  if (phrase.length === 0) {
    return { letters: [], scale: 1 };
  }
  const unit = [...phrase, ...Array.from(SEPARATOR)];
  const unitWidth = widthOf(unit);
  const repeats = repeatsFor(unitWidth);
  const natural = repeats * unitWidth;
  const scale = Math.min(1, CIRCUMFERENCE_EM / natural);
  const leftOver = CIRCUMFERENCE_EM - natural * scale;
  const spacing = leftOver / (repeats * unit.length);
  const slots = slotsOf(unit, repeats, scale, spacing);
  const lastIndex = phrase.length - 1;
  const lastOfPhrase = slots[lastIndex];
  const lastWidth = advanceOf(lastOfPhrase.char) * scale + spacing;
  const phraseLength = lastOfPhrase.centre + lastWidth / 2;
  const offset = (phraseLength / 2 / CIRCUMFERENCE_EM) * 360;
  const inked = slots.filter((slot) => slot.char !== ' ');
  const letters = inked.map((slot) => ({
    char: slot.char,
    angle: angleOf(slot.centre, offset),
  }));
  return { letters, scale };
}

'use client';

import { useState } from 'react';

/** Whether a mouse or a pen rests on an element. A finger does not hover, so a touch never counts. */
export function useHover() {
  const [isHovered, setIsHovered] = useState(false);

  function hoverStarts(event: React.PointerEvent<HTMLElement>) {
    if (event.pointerType !== 'touch') {
      setIsHovered(true);
    }
  }

  function hoverEnds() {
    setIsHovered(false);
  }

  const hoverHandlers = {
    onPointerEnter: hoverStarts,
    onPointerLeave: hoverEnds,
  };

  return { isHovered, hoverHandlers };
}

'use client';

import { useInView } from 'motion/react';
import { useRef } from 'react';

import { useDocumentVisible } from '@/registry/ndeko/hooks/use-agent-run';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';

/**
 * A badge that moves on its own plays only while someone can see it: on screen, in the tab that is
 * shown, without reduced motion. Everything that repeats hangs on `isPlaying`, and `isStill` asks
 * for the resting picture.
 */
export function usePlayWhileSeen<Element extends HTMLElement = HTMLElement>() {
  const ref = useRef<Element>(null);
  const isInView = useInView(ref);
  const isTabVisible = useDocumentVisible();
  const isStill = usePrefersReducedMotion();
  const isOnScreen = isInView && isTabVisible;
  const isPlaying = isOnScreen && !isStill;

  return { ref, isPlaying, isStill };
}
